create table if not exists public.marketplace_operator_alerts(id uuid primary key default gen_random_uuid(),product_key text not null check(product_key in ('on_call','sos')),alert_type text not null,entity_id uuid,title text not null,body text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists marketplace_operator_alerts_created_idx on public.marketplace_operator_alerts(created_at desc);
create table if not exists public.marketplace_operator_alert_reads(alert_id uuid not null references public.marketplace_operator_alerts(id) on delete cascade,operator_auth_id uuid not null,read_at timestamptz not null default now(),primary key(alert_id,operator_auth_id));
alter table public.marketplace_operator_alerts enable row level security;alter table public.marketplace_operator_alert_reads enable row level security;revoke all on public.marketplace_operator_alerts from anon,authenticated;revoke all on public.marketplace_operator_alert_reads from anon,authenticated;
create or replace function private.marketplace_emit_operator_alert(p_product_key text,p_alert_type text,p_entity_id uuid,p_title text,p_body text,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path='pg_catalog','public','private' as $$ begin if p_product_key not in ('on_call','sos') then raise exception 'Invalid product key'; end if; insert into public.marketplace_operator_alerts(product_key,alert_type,entity_id,title,body,metadata) values(p_product_key,left(p_alert_type,80),p_entity_id,left(p_title,180),left(coalesce(p_body,''),1000),coalesce(p_metadata,'{}'::jsonb)); end;$$;revoke all on function private.marketplace_emit_operator_alert(text,text,uuid,text,text,jsonb) from public,anon,authenticated;
create or replace function public.marketplace_ops_alert_feed(p_limit integer default 50) returns table(id uuid,product_key text,alert_type text,entity_id uuid,title text,body text,metadata jsonb,created_at timestamptz,is_read boolean) language sql stable security definer set search_path='pg_catalog','public','private' as $$ select a.id,a.product_key,a.alert_type,a.entity_id,a.title,a.body,a.metadata,a.created_at,exists(select 1 from public.marketplace_operator_alert_reads r where r.alert_id=a.id and r.operator_auth_id=auth.uid()) from public.marketplace_operator_alerts a where public.marketplace_operator_check() order by a.created_at desc limit greatest(1,least(coalesce(p_limit,50),100)) $$;revoke all on function public.marketplace_ops_alert_feed(integer) from public,anon;grant execute on function public.marketplace_ops_alert_feed(integer) to authenticated;
create or replace function public.marketplace_ops_mark_alert_read(p_alert_id uuid) returns boolean language plpgsql security definer set search_path='pg_catalog','public','private' as $$ begin if auth.uid() is null or not public.marketplace_operator_check() then raise exception 'Marketplace operator access required' using errcode='42501'; end if;if not exists(select 1 from public.marketplace_operator_alerts where id=p_alert_id) then return false; end if;insert into public.marketplace_operator_alert_reads(alert_id,operator_auth_id) values(p_alert_id,auth.uid()) on conflict(alert_id,operator_auth_id) do update set read_at=now();return true;end;$$;revoke all on function public.marketplace_ops_mark_alert_read(uuid) from public,anon;grant execute on function public.marketplace_ops_mark_alert_read(uuid) to authenticated;
create or replace function public.oc_provider_application_operator_alert_trigger() returns trigger language plpgsql security definer set search_path='pg_catalog','public','private' as $$ begin if tg_op='INSERT' then perform private.marketplace_emit_operator_alert('on_call','provider_application_submitted',new.id,'New ON CALL provider application',coalesce(new.first_name,'')||' '||coalesce(new.last_name,'')||' · '||coalesce(new.city,'')||', '||coalesce(new.state_code,''),jsonb_build_object('application_number',new.application_number,'status',new.status));elsif old.status is distinct from new.status then perform private.marketplace_emit_operator_alert('on_call','provider_application_status',new.id,'ON CALL provider application updated',coalesce(new.application_number,'Application')||' → '||new.status,jsonb_build_object('application_number',new.application_number,'old_status',old.status,'new_status',new.status));end if;return new;end;$$;revoke all on function public.oc_provider_application_operator_alert_trigger() from public,anon,authenticated;drop trigger if exists oc_provider_application_operator_alert on public.oc_provider_applications;create trigger oc_provider_application_operator_alert after insert or update of status on public.oc_provider_applications for each row execute function public.oc_provider_application_operator_alert_trigger();
create or replace function public.sos_hero_application_operator_alert_trigger() returns trigger language plpgsql security definer set search_path='pg_catalog','public','private' as $$ begin if tg_op='INSERT' then perform private.marketplace_emit_operator_alert('sos','hero_application_submitted',new.id,'New S.O.S. Hero application',coalesce(new.first_name,'')||' '||coalesce(new.last_name,'')||' · '||coalesce(new.city,'')||', '||coalesce(new.state,''),jsonb_build_object('status',new.status));elsif old.status is distinct from new.status then perform private.marketplace_emit_operator_alert('sos','hero_application_status',new.id,'S.O.S. Hero application updated','Hero application → '||new.status,jsonb_build_object('old_status',old.status,'new_status',new.status));end if;return new;end;$$;revoke all on function public.sos_hero_application_operator_alert_trigger() from public,anon,authenticated;drop trigger if exists sos_hero_application_operator_alert on public.sos_hero_applications;create trigger sos_hero_application_operator_alert after insert or update of status on public.sos_hero_applications for each row execute function public.sos_hero_application_operator_alert_trigger();